package com.techie345.moneys.financial.holding;
import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import com.techie345.moneys.financial.FinancialEntity; import jakarta.persistence.*;
@Entity @Table(name="holding") public class HoldingEntity extends FinancialEntity {
 @Column(name="account_id",nullable=false) UUID accountId; @Column(nullable=false,length=32) String symbol; @Column(nullable=false,precision=24,scale=8) BigDecimal shares; @Column(name="cost_basis_cents",nullable=false) long costBasisCents; @Column(name="market_value_cents",nullable=false) long marketValueCents; String source; @Column(name="source_file") String sourceFile; @Column(name="imported_at") Instant importedAt;
 protected HoldingEntity(){} public HoldingEntity(UUID o,UUID a,String s,BigDecimal sh,long c,long m,String so,String sf,Instant i){if(o==null||a==null||s==null||s.isBlank()||sh==null||sh.signum()<0||c<0||m<0)throw new IllegalArgumentException("invalid holding");ownerId=o;accountId=a;symbol=s;shares=sh;costBasisCents=c;marketValueCents=m;source=so;sourceFile=sf;importedAt=i;} public UUID getAccountId(){return accountId;} public String getSymbol(){return symbol;} public BigDecimal getShares(){return shares;} public long getCostBasisCents(){return costBasisCents;} public long getMarketValueCents(){return marketValueCents;} public String getSource(){return source;} public String getSourceFile(){return sourceFile;} public Instant getImportedAt(){return importedAt;} public void update(UUID a,String s,BigDecimal sh,long c,long m,String so,String sf,Instant i){if(a==null||s==null||s.isBlank()||sh==null||sh.signum()<0||c<0||m<0)throw new IllegalArgumentException("invalid holding");accountId=a;symbol=s;shares=sh;costBasisCents=c;marketValueCents=m;source=so;sourceFile=sf;importedAt=i;}
}
